export type RateCircuitBreakerState = "closed" | "open" | "half-open";

export interface RateCircuitBreakerOptions {
  /** Number of failures in the sliding observation window that opens the circuit. */
  failureThreshold: number;
  /** Length of the sliding failure window, in milliseconds. */
  windowMs: number;
  /** Length of the open interval, in milliseconds. */
  cooldownMs: number;
  /** Injectable monotonic clock. */
  now?: () => number;
}

export interface RateCircuitBreakerSnapshot {
  state: RateCircuitBreakerState;
  failuresInWindow: number;
  openedAt: number | null;
  cooldownEndsAt: number | null;
  probeInFlight: boolean;
}

/**
 * A small, deterministic circuit breaker for exceptional call rates.
 *
 * This component is deliberately a rate boundary, not a general request limiter. It
 * does not make network calls, enforce budgets, inspect URLs, or change approval
 * policy. Callers must continue applying those controls before an allowed request
 * is executed.
 */
export class RateCircuitBreaker {
  private readonly failureThreshold: number;
  private readonly windowMs: number;
  private readonly cooldownMs: number;
  private readonly clock: () => number;

  private currentState: RateCircuitBreakerState = "closed";
  private readonly failures: number[] = [];
  private openedAt: number | null = null;
  private cooldownEndsAt: number | null = null;
  private probeInFlight = false;
  private closedRequestInFlight = false;

  constructor(options: RateCircuitBreakerOptions) {
    if (!Number.isFinite(options.failureThreshold) || options.failureThreshold < 1) {
      throw new RangeError("failureThreshold must be a positive finite number");
    }
    if (!Number.isFinite(options.windowMs) || options.windowMs <= 0) {
      throw new RangeError("windowMs must be a positive finite number");
    }
    if (!Number.isFinite(options.cooldownMs) || options.cooldownMs < 0) {
      throw new RangeError("cooldownMs must be a non-negative finite number");
    }
    this.failureThreshold = options.failureThreshold;
    this.windowMs = options.windowMs;
    this.cooldownMs = options.cooldownMs;
    this.clock = options.now ?? Date.now;
  }

  get state(): RateCircuitBreakerState {
    this.advanceState(this.clock());
    return this.currentState;
  }

  /**
   * Reserves capacity for one request. A true result means that the caller may
   * execute the request; false means it must be rejected without side effects.
   */
  allowRequest(now = this.clock()): boolean {
    this.advanceState(now);

    if (this.currentState === "open") {
      return false;
    }

    if (this.currentState === "half-open") {
      if (this.probeInFlight) {
        return false;
      }
      this.probeInFlight = true;
      return true;
    }

    // Closed is not a concurrency limiter. This marker only prevents an
    // unmatched probe result from being interpreted as a probe result.
    this.closedRequestInFlight = true;
    return true;
  }

  /** Alias suitable for use as a boundary predicate. */
  allow(now = this.clock()): boolean {
    return this.allowRequest(now);
  }

  /** Alias suitable for callers that use gate terminology. */
  beforeRequest(now = this.clock()): boolean {
    return this.allowRequest(now);
  }

  recordSuccess(now = this.clock()): void {
    this.advanceState(now);
    if (this.currentState === "half-open" && this.probeInFlight) {
      this.probeInFlight = false;
      this.currentState = "closed";
      this.failures.length = 0;
      this.openedAt = null;
      this.cooldownEndsAt = null;
      return;
    }
    if (this.currentState === "closed") {
      this.closedRequestInFlight = false;
    }
  }

  recordFailure(now = this.clock()): void {
    this.advanceState(now);

    if (this.currentState === "half-open" && this.probeInFlight) {
      this.probeInFlight = false;
      this.open(now);
      return;
    }

    if (this.currentState !== "closed") {
      return;
    }

    this.closedRequestInFlight = false;
    this.pruneFailures(now);
    this.failures.push(now);
    if (this.failures.length >= this.failureThreshold) {
      this.open(now);
    }
  }

  /** Aliases for integrations that report execution results. */
  onSuccess(now = this.clock()): void {
    this.recordSuccess(now);
  }

  onFailure(now = this.clock()): void {
    this.recordFailure(now);
  }

  success(now = this.clock()): void {
    this.recordSuccess(now);
  }

  failure(now = this.clock()): void {
    this.recordFailure(now);
  }

  snapshot(now = this.clock()): RateCircuitBreakerSnapshot {
    this.advanceState(now);
    this.pruneFailures(now);
    return {
      state: this.currentState,
      failuresInWindow: this.failures.length,
      openedAt: this.openedAt,
      cooldownEndsAt: this.cooldownEndsAt,
      probeInFlight: this.probeInFlight,
    };
  }

  reset(): void {
    this.currentState = "closed";
    this.failures.length = 0;
    this.openedAt = null;
    this.cooldownEndsAt = null;
    this.probeInFlight = false;
    this.closedRequestInFlight = false;
  }

  private advanceState(now: number): void {
    if (this.currentState === "open" && this.cooldownEndsAt !== null && now >= this.cooldownEndsAt) {
      this.currentState = "half-open";
      this.probeInFlight = false;
    }
  }

  private open(now: number): void {
    this.currentState = "open";
    this.openedAt = now;
    this.cooldownEndsAt = now + this.cooldownMs;
    this.probeInFlight = false;
  }

  private pruneFailures(now: number): void {
    const cutoff = now - this.windowMs;
    while (this.failures.length > 0 && this.failures[0] <= cutoff) {
      this.failures.shift();
    }
  }
}

export { RateCircuitBreaker as CircuitBreaker };

