    this.advanceState(now);
    if (this.currentState === "half-open" && this.probeInFlight) {
      this.probeInFlight = false;
      this.currentState = "closed";
      this.failures.length = 0;
      this.openedAt = null;
      this.cooldownEndsAt = null;
      return;
