  onSuccess(now = this.clock()): void {
    this.recordSuccess(now);
  }

  onFailure(now = this.clock()): void {
    this.recordFailure(now);
  }

  success(now = this.clock()): void {
    this.recordSuccess(now);
  }

  failure(now = this.clock()): void {
    this.recordFailure(now);
  }

  snapshot(now = this.clock()): RateCircuitBreakerSnapshot {
    this.advanceState(now);
    this.pruneFailures(now);
    return {
      state: this.currentState,
      failuresInWindow: this.failures.length,
      openedAt: this.openedAt,
      cooldownEndsAt: this.cooldownEndsAt,
      probeInFlight: this.probeInFlight,
    };
  }

